import{z as s,x as l,o as n,c as d,q as A,j as i,D as E,d as B,s as r,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"教育财政","description":"","frontmatter":{"title":"教育财政","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ed2-education-finance.md","filePath":"econ/ed2-education-finance.md","lastUpdated":1791063341000}'),c={name:"econ/ed2-education-finance.md"};function u(p,a,D,h,m,f){const o=l("Mermaid");return n(),d("div",null,[a[2]||(a[2]=A('<h1 id="教育财政" tabindex="-1">教育财政 <a class="header-anchor" href="#教育财政" aria-label="Permalink to &quot;教育财政&quot;">​</a></h1><div class="epigraph"><p>学校的钱在谁手里，比钱有多少更早地决定了钱花到哪去——财政不是教育的后勤，是它的宪法。</p><footer>—— 据 Card and Payne, Journal of Public Economics 2002；Jackson, Johnson and Persico, QJE 2016 整理</footer></div><p><a href="/econ/ed2-skill-formation">上一课</a>说了钱该花在什么时候；本课说钱从哪里来、经过什么管道、落到谁头上。前几课的生产函数、教师与择校都默认预算存在；把预算本身打开，才发现它的分配规则先于一切教学决策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>美国的地方财政以财产税供养学区，于是税基厚薄直接决定学生资源：相邻两个学区，生均支出可以差出一倍。公平诉讼由此展开——Serrano v. Priest（加州，1971）以「财产税财政违宪」的口径宣战，Rodriguez（联邦最高法院，1973）则拒绝把教育升格为联邦宪法的基本权利，战场从此转到州法院。规范之争有两杆尺：均等（equalization，拉平支出）与充足（adequacy，托底到足够让学生达标），再加一杆效率尺：中央拨款会不会挤出地方自己的努力。<a href="/econ/public-goods">公共物品与免费搭车</a>的分权逻辑在这里被反过来用——教育是最重的辖区公共品，分权给了偏好匹配，也给了不平等。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>拨款的管道写进公式。基础拨款（foundation grant）的形状是</p> \\[G_i = \\max\\{0,\\; E^{*} - \\tau v_i\\}, \\]<p>即州政府按标准支出 \\(E^{*}\\) 减去地方应尽努力 \\(\\tau v_i\\)（\\(v_i\\) 为税基）补差额：税基越薄的学区拿得越多。<span class="marginnote">数字实例：设标准支出 \\(E^{*}=10000\\) 元/生、州定税率 \\(\\tau=2\\%\\)。甲学区税基 40 万/生，地方自筹 8000，州补 2000；乙学区税基 20 万/生，自筹 4000，州补 6000——税基越薄公式补得越多，这就是「托底」的机械含义。</span>配套款（matching grant）按地方每花一元州里补贴固定比例——它保地方努力，代价是富学区拿得也多；一次性 lump-sum 保均等，代价是挤出。两条管道对应<a href="/econ/tax-incidence">税收归宿</a>的通用教训：名义上给谁的钱，不等于最后落在谁头上的资源。而拨款的实际效果有个著名的异象——粘蝇纸效应（Hines–Thaler 1995）：公共拨款转化为支出的比例远高于同等规模的私人收入增长，钱粘在它落到的层级上，不会等比例漏进减税。<span class="marginnote">直觉类比：给学区拨款好比把零花钱直接塞进孩子的午餐信封——这钱多半真变成午餐，而不是被家里挪去还房贷；换成给家长涨工资，午餐预算未必多一分。「粘蝇纸」说的就是钱粘在它落到的层级上。</span></p>',9)),(n(),i(t,null,{default:E(()=>[r(o,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%9C%B0%E6%96%B9%E8%B4%A2%E4%BA%A7%E7%A8%8E%E5%9F%BA%20v_i%22%5D%20--%3E%20D%5B%22%E5%AD%A6%E5%8C%BA%E8%87%AA%E7%AD%B9%22%5D%0A%20%20S%5B%22%E5%B7%9E%E5%85%AC%E5%BC%8F%EF%BC%9A%E5%9F%BA%E7%A1%80%E6%8B%A8%E6%AC%BE%20%2F%20%E9%85%8D%E5%A5%97%E6%AC%BE%22%5D%20--%3E%20D%0A%20%20D%20--%3E%20IN%5B%22%E7%94%9F%E5%9D%87%E6%8A%95%E5%85%A5%EF%BC%9A%E5%B8%88%E7%94%9F%E6%AF%94%E3%80%81%E6%95%99%E5%B8%88%E3%80%81%E5%AD%A6%E6%97%B6%22%5D%0A%20%20F%5B%22%E8%81%94%E9%82%A6%E4%B8%93%E9%A1%B9%EF%BC%9A%E4%BB%BD%E9%A2%9D%E5%B0%8F%E3%80%81%E5%B8%A6%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20IN%0A%20%20IN%20--%3E%20Y%5B%22%E5%AD%A6%E4%B8%9A%E4%BA%A7%E5%87%BA%22%5D%0A%20%20Y%20--%3E%20LR%5B%22%E6%88%90%E5%B9%B4%E6%94%B6%E5%85%A5%E4%B8%8E%E6%B5%81%E5%8A%A8%22%5D%0A%20%20CO%5B%22%E6%8C%A4%E5%87%BA%E5%9C%B0%E6%96%B9%E5%8A%AA%E5%8A%9B%EF%BC%9F%22%5D%20-.%E7%BA%A6%E6%9D%9F%20S%20%E7%9A%84%E8%AE%BE%E8%AE%A1.-%3E%20S%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"学校财政改革是这段财政史留下的自然实验序列。Card–Payne 2002：改革确实压缩了州内学区间的支出差距，SAT 的贫富分差小幅收窄——管道在动。Jackson–Johnson–Persico 2016 用改革时机做识别，读数是本课的锚：童年十二年被生均支出提高 10% 的低收入学区学生，完成教育多约 0.3 年，成年工资高约 7%，成年贫困率低约 3 个百分点；对高收入学区，同样的钱几乎没有可测效应。机制正是第一课的边际口径：钱在被约束的学区买到了师生比、教师质量与更长学时——平均上无效的投入，在缺钱的边际上有效。",-1)),a[5]||(a[5]=e("p",null,"改革的钱走到哪一步才读得出效果，可以沿「约束边际」这条线画出来。",-1)),(n(),i(t,null,{default:E(()=>[r(o,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%B4%A2%E6%94%BF%E6%94%B9%E9%9D%A9%E5%88%A4%E5%86%B3%22%5D%20--%3E%20P%5B%22%E4%BD%8E%E6%94%B6%E5%85%A5%E5%AD%A6%E5%8C%BA%E7%94%9F%E5%9D%87%E6%94%AF%E5%87%BA%20%2B10%25%22%5D%0A%20%20P%20--%3E%20B1%5B%22%E5%B8%88%E7%94%9F%E6%AF%94%E4%B8%8E%E6%95%99%E5%B8%88%E8%B4%A8%E9%87%8F%E6%94%B9%E5%96%84%22%5D%0A%20%20P%20--%3E%20B2%5B%22%E5%AD%A6%E6%97%B6%E5%BB%B6%E9%95%BF%22%5D%0A%20%20B1%20--%3E%20OUT%5B%22%E6%88%90%E5%B9%B4%E7%BB%93%E6%9E%9C%3A%20%E5%8F%97%E6%95%99%E8%82%B2%20%2B0.3%20%E5%B9%B4%2C%20%E5%B7%A5%E8%B5%84%20%2B7%25%22%5D%0A%20%20B2%20--%3E%20OUT%0A%20%20R%20--%3E%20H%5B%22%E9%AB%98%E6%94%B6%E5%85%A5%E5%AD%A6%E5%8C%BA%3A%20%E9%92%B1%E4%B8%8D%E8%90%BD%E5%9C%A8%E7%BA%A6%E6%9D%9F%E8%BE%B9%E9%99%85%22%5D%0A%20%20H%20--%3E%20OUT0%5B%22%E5%B9%B3%E5%9D%87%E4%B8%8A%E5%87%A0%E4%B9%8E%E6%97%A0%E5%8F%AF%E6%B5%8B%E6%95%88%E5%BA%94%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">常见误区：把 JJP 的读数听成「多花钱就能提升成绩」。它说的是改革年代的边际美元、花在低收入学区、花在童年十二年的效果；不带治理结构与对象条件的「加钱万能论」，Hanushek 2003 的批评照样适用。</span></p><p><span class="marginnote">Rodriguez 的判词把教育排除出联邦宪法的基本权利，此后五十年的教育财政诉讼全部转进州宪法——「充足性」条款几乎在每个州都打过一轮，法院成了教育预算的实际设计者之一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Jackson–Johnson–Persico 的口径要钉住：改革年代的边际美元、低收入学区的儿童——不是「任何钱在任何地方都有用」的普适结论，Hanushek 2003 对简单加钱的批评依然成立：不带着治理结构加钱，支出照样蒸发在薪级表与楼宇里。联邦份额小（美国联邦拨款常在一成以下），体系的重心在州与地方。高等教育端另有财政问题——助学金、贷款与学费贴补的取舍是<a href="/econ/ed2-higher-ed">高等教育经济学</a>的财政面，本课的辖区逻辑到高中为止。最后，公式的政治经济学没有解：税基分拣会随财政均等化重新调整居住选择，分拣与均等在均衡里互相追着改写。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>财产税财政让税基决定资源，Serrano 与 Rodriguez 把公平之战定在州宪法。</li><li>拨款公式是设计变量：基础拨款保托底，配套款保努力，lump-sum 保均等但挤出。</li><li>粘蝇纸效应：公共拨款比私人收入更全额地转化为支出。</li><li>边际读数：改革抬高低收入学区生均支出 10%，成年工资约高 7%（JJP 2016）。</li><li>出处：Card and Payne, JPubE 2002；Jackson, Johnson and Persico, QJE 2016；Hines and Thaler, JEP 1995；Hanushek, Economic Journal 2003。</li></ul>',6))])}const C=s(c,[["render",u]]);export{P as __pageData,C as default};
